#!/bin/bash
# export: a dry run prints one request line per batch.
fail=0
bash bin/export --rows 10 --dry-run | grep -q '^POST /v2/batch rows=1-10 ' || { echo "export dry-run"; fail=1; }
bash bin/export --bogus >/dev/null 2>&1; [ $? = 2 ] || { echo "export usage"; fail=1; }
exit $fail
bash bin/export --rows 600 --dry-run | grep -q 'rows=1-250 ' || { echo "export batch 250"; fail=1; }
bash bin/export --rows 600 --dry-run | grep -q 'rows=501-600 ' || { echo "export remainder"; fail=1; }
bash bin/export --rows 10 --dry-run | grep -q ' X-Relay-Key$' || { echo "export auth header"; fail=1; }
exit $fail
